def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip().lower()

        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1).strip()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        extension = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()

        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value[:5]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Rows without either usable identifier cannot participate in matching.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        }

        normalized.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "tags": tags,
            "opted_out": is_opted_out(row["opted_out"]),
            "updated": parse_updated(row["updated"]),
            "source": row["source"].strip().lower(),
        })

    # Disjoint-set structure for transitive matching.
    parent = list(range(len(normalized)))
    rank = [0] * len(normalized)

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for position, row in enumerate(normalized):
        if row["email"]:
            previous = by_email.get(row["email"])
            if previous is None:
                by_email[row["email"]] = position
            else:
                union(position, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = by_phone_and_last_name.get(key)
            if previous is None:
                by_phone_and_last_name[key] = position
            else:
                union(position, previous)

    groups = {}
    for position, row in enumerate(normalized):
        groups.setdefault(find(position), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field] != ""]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated"],
                -row["index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated"] for row in group)

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
            "_earliest_index": min(row["index"] for row in group),
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
